import { Injectable, inject } from '@angular/core';
import { PerfilUsuarioLogin, UsuarioLogin } from '../../auth/auth.model';
import { LoginCliente } from '../../clientes/auth/auth.service';


@Injectable({
  providedIn: 'root'
})
export class LocalStorageService {

  constructor() { }

  ///Almacena una variable y objeto en local storage
  setData(key:string, value:any) : void { localStorage.setItem(key, JSON.stringify(value)); }

  ///Obtiene los datos guardados en la variable key
  getData<T=any>(key: string): T|null {
    const item = localStorage.getItem(key);
    try{
      if(item){
        return JSON.parse(item) as T
      }
    }catch(e){
      return null
    }
    return null
  }

  deleteData(key: string): void { localStorage.removeItem(key); }

  //Elimina todos los datos de caché
  deleteAll(): void {  localStorage.clear(); }

  ///Agrega los datos de sesión de un usuario al sistema
  setUser(userData:UsuarioLogin) : void { this.setData('user', userData); }

  setClienteUser(login:LoginCliente){
    this.setData('token_cliente', login)
    this.setData('cliente_data', login)
  }

  getClienteUser(){
    const user=this.getData('cliente_data') as LoginCliente|undefined
    return user
  }

  isUserLogged(){
    const user=this.getData('user') as UsuarioLogin|undefined
    return !!user
  }

  getUser():UsuarioLogin{
    const user=this.getData('user') as UsuarioLogin
    if(!user){
      throw new Error("Usuario no logeado");
    }
    return  user
  }

  setPerfil(perfil:PerfilUsuarioLogin){
    this.setData('perfil',perfil)
  }

  getPerfil():PerfilUsuarioLogin{
    const perfil=this.getData('perfil') as PerfilUsuarioLogin
    if(!perfil){
      throw new Error("Perfil no guardado");
    }
    return  perfil
  }

  deleteUser() : void {
    this.deleteData('user');
    this.deleteData('cliente_data');
  }

  /**
   * Returns token if user is logged, otherwise return empty string
   * @returns {string} token
   */
  getUserToken() : string {
    if(this.isUserLogged()){
      return this.getUser().token
    }
    if(this.getClienteUser()){
      return this.getClienteUser()?.token??''
    }
    return ''
  }
}
